feed:
{%- if term is defined %}
   {{ term.name }} - {{ config.title }}
{%- if taxonomy.name == "author" %}
  {{ theme_i18n["author_title"] | default(value="") }}：{{ term.name }} - {{ config.description }}
{%- elif taxonomy.name == "tags" %}
  {{ theme_i18n["tags_title"] | default(value="") }}：{{ term.name }} - {{ config.description }}
{%- else %}
  {{ taxonomy.name }} / {{ term.name }} - {{ config.description }}
{%- endif %}
  {%- set feed_self = term.permalink ~ "/atom.xml" %}
{%- else %}
  {{ config.title }}
  {{ config.description }}
  {%- set feed_self = get_url(path="atom.xml") %}
{%- endif %}

{%- if term is defined %}

{%- else %}

{%- endif %}
  Zola
{%- if pages | length > 0 %}
{%- set newest = pages[0].updated or pages[0].date %}
  {{ newest | date(format="%Y-%m-%dT%H:%M:%S+00:00") }}
{%- endif %}
  {{ feed_self | safe }}
{% for page in pages %}
{%- set authors = page.taxonomies.author | default(value=[]) %}
{%- set tags    = page.taxonomies.tags    | default(value=[]) %}
{%- set pub     = page.date %}
{%- set upd     = page.updated or page.date %}

    {{ page.title }}
    {{ pub | date(format="%Y-%m-%dT%H:%M:%S+00:00") }}
    {{ upd | date(format="%Y-%m-%dT%H:%M:%S+00:00") }}
{%- if authors | length > 0 %}
{%- for author_name in authors %}

      {{ author_name }}
      {{ get_taxonomy_url(kind='author', term=author_name) | trim_end(pat='/') | safe }}

{%- endfor %}
{%- else %}

      {{ config.author | default(value=config.title) }}

{%- endif %}
{%- for tag in tags %}

{%- endfor %}

    {{ page.permalink | trim_end(pat='/') | safe }}
{%- if page.extra.abstract %}
    {{ page.extra.abstract }}
{%- endif %}
{%- if page.extra.original %}

{%- endif %}

      {{ page.content }}


{% endfor %}
